UPDATE charge_package
name = #{name}, category_id = #{categoryId}, price = #{price}, origin_price = #{originPrice}, energy_kwh = #{energyKwh}, duration_minutes = #{durationMinutes}, times = #{times}, service_discount = #{serviceDiscount}, valid_days = #{validDays}, description = #{description}, image = #{image}, status = #{status}, sort = #{sort}, update_time = #{updateTime}, update_user = #{updateUser}
